CREATE VIEW MOGUDI_KOL_ANBARHA AS SELECT        TOP (100) PERCENT dbo.MOGUDI_KOL_ANBARHA_SUB.CODE, ROUND(ISNULL(dbo.MOGUDI_KOL_ANBARHA_SUB.MAND, 0), 2) AS MANDAH,                       dbo.MOGUDI_KOL_ANBARHA_SUB.MEGF, dbo.MOGUDI_KOL_ANBARHA_SUB.MABLK, dbo.MOGUDI_KOL_ANBARHA_SUB.SumOfMEG,                         dbo.MOGUDI_KOL_ANBARHA_SUB.NAME, dbo.MOGUDI_KOL_ANBARHA_SUB.NAMES, dbo.MOGUDI_KOL_ANBARHA_SUB.KK,                         dbo.MOGUDI_KOL_ANBARHA_SUB.VCOD , dbo.MOGUDI_KOL_ANBARHA_SUB.KINDK, dbo.STUF_DEF.N_FANI FROM            dbo.MOGUDI_KOL_ANBARHA_SUB INNER JOIN                         dbo.STUF_DEF ON dbo.MOGUDI_KOL_ANBARHA_SUB.CODE = dbo.STUF_DEF.CODE
